    --yellow:#F5C518;
    --black:#111111;
    --white:#FAF9F5;
    --paper:#F3F0E8;
    --line:#E2DED2;
  }
  *{box-sizing:border-box;margin:0}
  html{scroll-behavior:smooth}
  body{
    font-family:"Archivo",system-ui,sans-serif;
    background:var(--paper);
    color:var(--black);
    line-height:1.55;
    background-image:
      linear-gradient(var(--line) 1px, transparent 1px),
      linear-gradient(90deg, var(--line) 1px, transparent 1px);
    background-size:84px 84px;
  }
  .wrap{max-width:1180px;margin:0 auto;padding:0 24px}

  /* ---------- header ---------- */
  header{border-bottom:3px solid var(--black);background:var(--white)}
  .top{display:flex;justify-content:space-between;align-items:baseline;gap:16px;padding:14px 0}
  .brand{font-weight:900;letter-spacing:.06em;text-transform:uppercase;font-size:.95rem}
  .brand i{display:inline-block;width:.55em;height:.55em;background:var(--red);margin-right:.6em;transform:translateY(2px)}
  .top .meta{font-weight:700;font-size:.8rem;letter-spacing:.14em;text-transform:uppercase;color:#666}

  /* ---------- hero ---------- */
  .hero{display:grid;grid-template-columns:1.05fr 1fr;gap:56px;padding:64px 0 72px;align-items:center}

  .art{
    display:grid;
    grid-template-columns:34% 1fr 32%;
    grid-template-rows:50% 1fr;
    gap:14px;
    background:var(--black);
    padding:14px;
    aspect-ratio:31/30;
    box-shadow:10px 10px 0 var(--black);
  }
  .art .cell{animation:rise .7s both}
  .art .cell:nth-child(2){animation-delay:.08s}
  .art .cell:nth-child(3){animation-delay:.16s}
  .art .cell:nth-child(4){animation-delay:.24s}
  .art .cell:nth-child(5){animation-delay:.32s}
  .art .cell:nth-child(6){animation-delay:.4s}
  .c-white{background:var(--white)}
  .c-red{background:var(--red)}
  .c-blue{background:var(--blue)}
  .c-yellow{background:var(--yellow)}
  @keyframes rise{from{opacity:0;transform:translateY(14px)}}

  .kicker{
    display:inline-block;font-weight:700;font-size:.82rem;letter-spacing:.16em;
    text-transform:uppercase;border-left:6px solid var(--red);padding-left:12px;margin-bottom:18px;
  }
  h1{
    font-weight:900;text-transform:uppercase;letter-spacing:-.015em;
    font-size:clamp(2rem,4.6vw,3.4rem);line-height:1.02;margin-bottom:20px;
  }
  h1 .r{color:var(--red)} h1 .b{color:var(--blue)} h1 .y{color:#B8860B}
  .lede{font-size:1.06rem;max-width:46ch;margin-bottom:28px}
  .facts{display:grid;grid-template-columns:1fr 1fr;gap:0 28px;margin-bottom:32px}
  .facts > div{border-top:2px solid var(--black);padding:10px 0 14px}
  .facts dt{font-size:.72rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#666}
  .facts dd{font-weight:700;font-size:1.02rem;margin-top:2px}
  .cta{
    display:inline-block;background:var(--black);color:var(--white);text-decoration:none;
    font-weight:700;text-transform:uppercase;letter-spacing:.1em;font-size:.85rem;
    padding:14px 22px;border:3px solid var(--black);
    transition:background .15s,color .15s;
  }
  .cta:hover{background:var(--red);border-color:var(--red)}

